package main
import("context";"encoding/json";"fmt";"os";"runtime";"runtime/pprof";"dircue/internal/cli";"dircue/pkg/profile")
func main(){
 runtime.MemProfileRate=1
 dir:=os.Getenv("DIRCUE_PROFILE_DIR")
 var before,after,live runtime.MemStats
 runtime.ReadMemStats(&before)
 var err error
 if os.Getenv("DIRCUE_PROFILE_KIND")=="empty" { var b []byte;b,err=json.Marshal(&profile.Report{});if err==nil{os.Stdout.Write(b)}} else {err=cli.Execute(context.Background(),os.Args[1:],os.Stdout,os.Stderr)}
 runtime.ReadMemStats(&after)
 runtime.GC();runtime.ReadMemStats(&live)
 out,_:=os.Create(dir+"/allocs.pprof");pprof.Lookup("allocs").WriteTo(out,0);out.Close()
 out,_=os.Create(dir+"/heap.pprof");pprof.WriteHeapProfile(out);out.Close()
 out,_=os.Create(dir+"/stats.json");json.NewEncoder(out).Encode(map[string]any{"before":before,"after":after,"live":live,"allocated_bytes":after.TotalAlloc-before.TotalAlloc,"allocation_count":after.Mallocs-before.Mallocs});out.Close()
 if err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)}
}
